class ArgumentParser:  
    """
    This is a class for parsing command line arguments to a dictionary.
    """

    def __init__(self):
        """
        Initialize the fields.
        self.arguments is a dict that stores the args in a command line
        self.required is a set that stores the required arguments
        self.types is a dict that stores type of every arguments.
        >>> parser.arguments
        {'key1': 'value1', 'option1': True}
        >>> parser.required
        {'arg1'}
        >>> parser.types
        {'arg1': 'type1'}
        """
        self.arguments = {}
        self.required = set()
        self.types = {}



    def parse_arguments(self, command_string):
        """
        Parses the given command line argument string and invoke _convert_type to stores the parsed result in specific type in the arguments dictionary.
        Checks for missing required arguments, if any, and returns False with the missing argument names, otherwise returns True.
        :param command_string: str, command line argument string, formatted like "python script.py --arg1=value1 -arg2 value2 --option1 -option2"
        :return tuple: (True, None) if parsing is successful, (False, missing_args) if parsing fails,
            where missing_args is a set of the missing argument names which are str.
        >>> parser.parse_arguments("python script.py --arg1=value1 -arg2 value2 --option1 -option2")
        (True, None)
        >>> parser.arguments
        {'arg1': 'value1', 'arg2': 'value2', 'option1': True, 'option2': True}
        """
        args = command_string.split()
        for arg in args:
            if arg.startswith('--'):
                arg_name = arg[2:]
                if arg_name in self.arguments:
                    self.arguments[arg_name] = self._convert_type(arg_name, args[args.index(arg) + 1])
                else:
                    self.required.add(arg_name)
            else:
                self.types[arg] ='str'
        return True, None if len(self.required) == 0 else self.required



    def _convert_type(self, arg_name, arg_value):
        """
        Converts the given argument value to the type specified in the arguments dictionary.
        :param arg_name: str, the name of the argument
        :param arg_value: str, the value of the argument
        :return: the converted value
        >>> parser._convert_type('arg1', 'value1')
        'value1'
        >>> parser._convert_type('arg1', 'value2')
        'value2'
        >>> parser._convert_type('arg1', 'value3')
        'value3'
        >>> parser._convert_type('arg1', 'value4')
        'value4'
        >>> parser._convert_type('arg1', 'value5')
        'value5'
        """
        if arg_name in self.types:
            if self.types[arg_name] == 'int':
                return int(arg_value)
            elif self.types[arg_name] == 'float':
                return float(arg_value)
            elif self.types[arg_name] == 'bool':
                return arg_value.lower() in ['true', '1']
            elif self.types[arg_name] =='str':
                return arg_value
        return arg_value



