class ClassRegistrationSystem:  
    """
    This is a class as a class registration system, allowing to register students, register them for classes, retrieve students by major, get a list of all majors, and determine the most popular class within a specific major.
    """

    def __init__(self):
        """
        Initialize the registration system with the attribute students and students_registration_class.
        students is a list of student dictionaries, each student dictionary has the key of name and major.
        students_registration_class is a dictionaries, key is the student name, value is a list of class names
        """
        self.students = []
        self.students_registration_classes = {}



    def register_student(self, student):
        """
        register a student to the system, add the student to the students list, if the student is already registered, return 0, else return 1
        """
        if student.name in self.students:
            return 0
        else:
            self.students.append(student)
            self.students_registration_classes[student.name] = []
            return 1

    def register_class(self, student, class_name):
        """
        register a class to the student, add the class to the student's list of classes, if the student is already registered for the class, return 0, else return 1
        """
        if student.name in self.students:
            if class_name in self.students_registration_classes[student.name]:
                return 0
            else:
                self.students_registration_classes[student.name].append(class_name)
                return 1
        else:
            return 0

    def get_student_by_name(self, name):
        """
        return the student with the name name, if the student is not registered, return None
        """
        for student in self.students:
            if student.name == name:
                return student
        return None

    def get_student_by_major(self, major):
        """
        return the student with the major major, if the student is not registered, return None
        """
        for student in self.students:
            if student.major == major:
                return student
        return None

    def get_student_classes(self, name):
        """
        return the list of classes the student name name has registered, if the student is not registered, return None
        """
        if name in self.students_registration_classes:
            return self.students_registration_classes[name]
        else:
            return None

    def get_all_students(self):
        """
        return the list of all students, including the students registered for each class
        """
        return self.students

    def get_all_classes(self):
        """
        return the list of all classes, including the classes registered for each student
        """
        return self.students_registration_classes

    def get_most_popular_class(self, name):
        """
        return the class with the most students, if the student is not registered, return None
        """
        if name in self.students_registration_classes:
            classes = self.students_registration_classes[name]
            classes.sort(key=len, reverse=True)
            return classes[0]
