import csv
class CSVProcessor:  
    """
    This is a class for processing CSV files, including readring and writing CSV data, as well as processing specific operations and saving as a new CSV file.
    """

    def __init__(self):
        pass



    def read_csv(self, file_name):
        """
        Read the csv file by file_name, get the title and data from it
        :param file_name: str, name of the csv file
        :return title, data: (list, list), first row is title, the rest is data
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.read_csv('read_test.csv')
        (['a', 'b', 'c', 'd'], [['hElLo', 'YoU', 'ME', 'LoW']])
        """
        with open(file_name, 'r') as f:
            reader = csv.reader(f)
            title = next(reader)
            data = list(reader)
        return title, data


    def write_csv(self, data, file_name):
        """
        Write data into a csv file.
        :param file_name: str, name of the csv file
        :return:int, if success return 1, or 0 otherwise
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.write_csv([['a', 'b', 'c', 'd'], ['1', '2', '3', '4']], 'write_test.csv')
        1
        """
        with open(file_name, 'w') as f:
            writer = csv.writer(f)
            writer.writerows(data)
        return 1


    def process_csv(self, file_name, operation, *args):
        """
        Process the csv file by file_name, and return the result.
        :param file_name: str, name of the csv file
        :param operation: str, operation to be performed, e.g.'sum'
        :param args: list, arguments to be passed to the operation
        :return: list, result of the operation
        >>> csvProcessor = CSVProcessor()
        >>> csvProcessor.process_csv('read_test.csv','sum', 1, 2)
        [3]
        """
        title, data = self.read_csv(file_name)
        if operation =='sum':
            result = [sum(x) for x in zip(data[0], *args)]
        elif operation =='max':
            result = [max(x) for x in zip(data[0], *args)]
        elif operation =='min':
            result = [min(x) for x in zip(data[0], *args)]
        elif operation =='mean':
            result = [sum(x) / len(x) for x in zip(data[0], *args)]
        elif operation =='median':
            result = [sorted(x)[len(x) // 2] for x in zip(data[0], *args)]
        elif operation =='mode':
            result = [sorted(x, key=lambda x: x.count(x[0]))[0] for x in zip(data[0], *args)]
        elif operation == 'unique':
            result = list(set(data[0]))
        elif operation == 'count':
            result = [len(x) for x in zip(data[0], *args)]
        elif operation == 'unique_count':
            result = [len(x) for x in zip(data[0], *args)]
        elif operation == 'unique_count_dict':
            result = {x: data[0].count(x) for x in set(data[0])}
        elif operation == 'unique_count_dict_sorted':
            result = {x: data[0].count(x) for x in sorted(set(data[0]), key=lambda x: x)}
        elif operation == 'unique_count_dict_sorted_reverse':
            result = {x: data[0].count(x) for x in sorted(set(data[0]), key=lambda x: x, reverse=True)}
        elif operation == 'unique_count_dict_sorted_reverse_dict':
            result = {x: data[0].count(x) for x in sorted(set(data[0]), key=lambda x: x, reverse=True)}
        elif operation == 'unique_count_dict_sorted_reverse_dict_sorted':
            result = {x: data[0].count(x) for x in sorted(set(data[0]), key=lambda x: x, reverse=True)}
        elif operation == 'unique_count_dict_sorted_reverse_dict_sorted_reverse':
