        """
        document = Document(self.file_path)
        paragraph = document.add_paragraph()
        paragraph.alignment = WD_PARAGRAPH_ALIGNMENT.LEFT
        paragraph.font.size = Pt(font_size)
        paragraph.text = content
        document.save(self.file_path)
        return True




