        :param data:list of data, Data to write
        :param file_name:str, Excel file name to write
        """
        wb = openpyxl.Workbook()
        sheet = wb.active
        for row in data:
            for cell in row:
                sheet.cell(row=1, column=cell.column_letter, value=cell.value)
        wb.save(file_name)

