        """
        Processing data in Excel files
        :param data:list of data, Data to process
        :param operation:str, Operation to perform
        :return:list of data, Data after performing operation
        """
        if operation == "add":
            for row in data:
                for cell in row:
                    cell.value += 1
        elif operation == "subtract":
            for row in data:
                for cell in row:
                    cell.value -= 1
        elif operation == "multiply":
            for row in data:
                for cell in row:
                    cell.value *= 2
        elif operation == "divide":
            for row in data:
                for cell in row:
                    cell.value /= 2
        return data

