    def __format_html_tags(text):
        """
        Replace HTML tags with their respective mark
        :param text: string with HTML tags
        :return: string, replaced text with mark
        """
        return re.sub(r'<[^>]*>', HtmlUtil.MARKUP_LANGUAGE_MARK, text)

