        self.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        self.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        self.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        self.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]



    def format(self, x):
        """
        Converts a number into words format
        :param x: int or float, the number to be converted into words format
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format(123456)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if isinstance(x, int):
            return self._format_int(x)
        elif isinstance(x, float):
            return self._format_float(x)
        else:
            raise TypeError("NumberWordFormatter.format() expects an int or float")


    def format_string(self, x):
        """
        Converts a string representation of a number into words format
        :param x: str, the string representation of a number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.format_string("123456")
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if not isinstance(x, str):
            raise TypeError("NumberWordFormatter.format_string() expects a string")
        if x.isdigit():
            return self._format_int(int(x))
        elif x.replace(".", "").isdigit():
            return self._format_float(float(x))
        else:
            raise TypeError("NumberWordFormatter.format_string() expects a string representation of a number")



    def trans_two(self, s):
        """
        Converts a two-digit number into words format
        :param s: str, the two-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_two("23")
        "TWENTY THREE"
        """
        if not isinstance(s, str):
            raise TypeError("NumberWordFormatter.trans_two() expects a string")
        if len(s)!= 2:
            raise TypeError("NumberWordFormatter.trans_two() expects a string of two digits")
        return self.NUMBER[int(s)] + " " + self.NUMBER_MORE[int(s[1])]




    def trans_three(self, s):
        """
        Converts a three-digit number into words format
        :param s: str, the three-digit number
        :return: str, the number in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter.trans_three("123")
        "ONE HUNDRED AND TWENTY THREE"
        """
        if not isinstance(s, str):
            raise TypeError("NumberWordFormatter.trans_three() expects a string")
        if len(s)!= 3:
            raise TypeError("NumberWordFormatter.trans_three() expects a string of three digits")
        return self.NUMBER[int(s[0])] + " " + self.NUMBER_MORE[int(s[1])] + " " + self.NUMBER_MORE[int(s[2])]





    def parse_more(self, i):
        """
        Parses the thousand/million/billion suffix based on the index
        :param i: int, the index representing the magnitude (thousand, million, billion)
        :return: str, the corresponding suffix for the magnitude
        >>> formatter = NumberWordFormatter()
        >>> formatter.parse_more(1)
        "THOUSAND"
        """
        if i == 0:
            return "THOUSAND"
        elif i == 1:
            return "MILLION"
        elif i == 2:
            return "BILLION"
        else:
            raise ValueError("NumberWordFormatter.parse_more() expects an index of 0, 1, or 2")




    def _format_int(self, x):
        """
        Formats an integer into words format
        :param x: int, the integer to be formatted
        :return: str, the integer in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter._format_int(123456)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if x == 0:
            return "ZERO"
        elif x < 20:
            return self.NUMBER[x]
        elif x < 100:
            return self.NUMBER_TEEN[x // 10] + " " + self.NUMBER_MORE[x % 10]
        elif x < 1000:
            return self.NUMBER_TEN[x // 100] + " " + self.NUMBER_MORE[x % 100]
        elif x < 1000000:
            return self.NUMBER_MORE[x // 1000] + " " + self.NUMBER_MORE[x % 1000] + " " + self.parse_more(x % 1000)
        else:
            return self.NUMBER_MORE[x // 1000000] + " " + self.NUMBER_MORE[x % 1000000] + " " + self.parse_more(x % 1000000)




    def _format_float(self, x):
        """
        Formats a float into words format
        :param x: float, the float to be formatted
        :return: str, the float in words format
        >>> formatter = NumberWordFormatter()
        >>> formatter._format_float(123456.789)
        "ONE HUNDRED AND TWENTY THREE THOUSAND FOUR HUNDRED AND FIFTY SIX ONLY"
        """
        if x == 0:
            return "ZERO"
        elif x < 20:
            return self.NUMBER[int(x)]
        elif x < 100:
            return self.NUMBER_TEEN[int(x // 10)] + " " + self.NUMBER_MORE[int(x % 10)]
        elif x < 1000:
            return self.NUMBER_TEN[int(x // 100)] + " " + self.NUMBER_MORE[int(x % 100)]
        elif x < 1000000:
            return self.NUMBER_MORE[int(x // 1000)] + " " + self.NUMBER_MORE[int(x % 1000)] + " " + self.parse_more(x % 1000)
        else:
            return self.NUMBER_MORE[int(x // 1000000)] + " " + self.NUMBER_MORE[int(x % 1000000)] + " " + self.parse_more(x % 1000000)




