import random
class TwentyFourPointGame:  
    """
    This ia a game of twenty-four points, which provides to generate four numbers and check whether player's expression is equal to 24.
    """

    def __init__(self) -> None:
        self.nums = []




    def _generate_cards(self):
        """
        Generate random numbers between 1 and 9 for the cards.
        """
        for i in range(0, 4):
            self.nums.append(random.randint(1, 9))
        return self.nums

    def _check_cards(self):
        """
        Check whether player's expression is equal to 24.
        """
        for i in range(0, 4):
            if self.nums[i] == 24:
                return True
        return False

    def _print_cards(self):
        """
        Print the cards.
        """
        for i in range(0, 4):
            print(self.nums[i])
        return self.nums

    def _play_cards(self):
        """
        Play the cards.
        """
        for i in range(0, 4):
            if self.nums[i] == 24:
                return True
        return False

    def _check_win(self):
        """
        Check whether player's expression is equal to 24.
        """
        for i in range(0, 4):
            if self.nums[i] == 24:
                return True
        return False

    def _print_win(self):
        """
        Print whether player's expression is equal to 24.
        """
        for i in range(0, 4):
            if self.nums[i] == 24:
                print("You win!")
                return True
        return False

    def _print_lose(self):
        """
        Print whether player's expression is equal to 24.
        """
        for i in range(0, 4):
            if self.nums[i]!= 24:
                print("You lose!")
                return True
        return False

    def play(self):
        """
        Play the game.
        """
        self.nums = self._generate_cards()
        while self._play_cards() == False:
            self.nums = self._generate_cards()
        while self._check_cards() == False:
            self.nums = self._generate_cards()
        while self._check_win() == False:
            self.nums = self._generate_cards()
        while self._print_cards() == False:
            self.nums = self._generate_cards()
        while self._print_win() == False:
            self.nums = self._generate_cards()
        while self._print_lose() == False:
            self.nums = self._generate_cards()
        return self.nums

if __name__ == "__main__":
    game = TwentyFourPointGame()
    print(game.play())

